#[effects(alloc)]
fn push_digit(out: &mut String, d: u32) -> () {
    let digit_code: u32 = if d < 10 {
        48 + d % 16
    } else {
        87 + d % 16
    };
    match char::from_u32(digit_code) {
        None => {},
        Some(c) => out.push(c),
    }
}

